{
  "name": "specrune-opencode",
  "version": "0.11.0",
  "description": "SpecRune 的 OpenCode 宿主插件与安装器：全局装配插件、代理、命令，并清理项目级旧文件",
  "type": "module",
  "bin": {
    "specrune-opencode": "bin/specrune-opencode.mjs"
  },
  "files": [
    "bin",
    "src",
    "lib",
    "agents",
    "commands",
    "README.md"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/SpecRune/SpecRune.git",
    "directory": "plugins/opencode"
  },
  "homepage": "https://github.com/SpecRune/SpecRune#readme",
  "bugs": {
    "url": "https://github.com/SpecRune/SpecRune/issues"
  },
  "license": "MIT",
  "keywords": [
    "specrune",
    "opencode",
    "plugin",
    "spec-driven",
    "workflow"
  ]
}

#!/usr/bin/env node
// specrune-opencode 的可执行入口。
//
// 包内只有这一个 bin：安装器负责把插件、代理与命令落到宿主目录，
// 不在 postinstall 里做任何事（pnpm 10 默认拦截依赖的生命周期脚本）。
// 共享核心缺失（旧版 specrune）等启动错误只打印可操作消息，不甩模块堆栈。
try {
  const { main } = await import("../src/install.mjs");
  process.exitCode = await main(process.argv.slice(2));
} catch (err) {
  process.stderr.write(`specrune-opencode: ${err?.message ?? err}\n`);
  process.exitCode = 1;
}

// SpecRune 的 OpenCode v2 宿主插件（由 OpenCode 以 Bun 加载，无编译步骤）。
//
// 落盘在 `.opencode/plugins/specrune.ts`，OpenCode 启动时自动加载该目录下的所有插件，
// 不需要任何配置挂载。
//
// 模块形状与钩子名是 OpenCode v2.0.15 的实测契约，不是文档抄写：
//   - 模块必须 `export default { id, setup }`，Effect schema 会校验这个形状。
//   - `setup(ctx)` 收到的是服务注册表（ctx.session / ctx.tool / ctx.shell /
//     ctx.permission / ctx.aisdk / ctx.rpc …），钩子用 `ctx.<域>.hook(名字, 处理器)`
//     命令式注册。注册时名字不做校验，名字打错就静默不触发。
//   - `session/prompt`  ：每条用户发言触发，载荷含 sessionID / prompt.text。
//   - `session/context` ：每轮组装 LLM 上下文时触发，载荷含 sessionID / agent /
//     system（{type:"text",text} 块数组）/ messages。往 system **追加**文本块即完成
//     稳定段注入：前面的块保持逐字节不变，provider 的前缀缓存不受影响
//     （req:injection-chain#injection-pipeline-hard-constraints）。易变段与 workflow-state 面包屑改走 messages——易变内容
//     禁入 system，而 messages 的改动只影响当次模型调用、不进持久历史。
//     messages 的 Message 形状为 { id, role, content:[{type,text}], metadata }，
//     字段是 `content` **不是** `parts`；push 无运行时校验，写错字段不报错但内容
//     不会到达模型（静默失效）。见 req:injection-runtime#opencode-rpc-injection。
//   - `tool/execute.before`：工具调用前触发，载荷含 tool / input，只读审计用。
//
// 注入与审计逻辑与具体 OpenCode 版本解耦：钩子名改了只改本文件顶部的注册表，
// 协议层（分帧、超时、微缓存、降级）不动。

import path from "node:path";
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";

// 二进制定位 + 熔断

// npm 全局安装的 Windows bin 只有 specrune.cmd，没有 .exe；spawn 不能直接执行
// .cmd（req:backend/npm-distribution#launcher-contract）。win32 下按
// SPECRUNE_BIN → specrune.exe → specrune.cmd 解析，.cmd 经 cmd.exe 拉起。
type BinarySpec = { command: string; viaCmd: boolean };

// findOnPath 在 PATH 里找一个存在的文件；名字自带扩展名，不做 PATHEXT 展开。
// 扫 PATH 而不是 `where`：省一次进程，且宿主启动路径上任何额外进程都要付
// 控制台闪窗与超时的代价。
function findOnPath(name: string): string | undefined {
  const raw = process.env["PATH"] ?? process.env["Path"] ?? "";
  for (const dir of raw.split(path.delimiter)) {
    if (!dir) continue;
    const candidate = path.join(dir, name);
    try {
      if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
    } catch {
      // 单个坏目录项不该让整条 PATH 解析失败。
    }
  }
  return undefined;
}

// npm 平台包映射表：唯一出处是 npm/cli/lib/platforms.cjs（installer-core 直接 import 它）。
// 运行时不能直接 import：`lib/` 只在 stage 出来的插件包里才存在，仓库内 link 形态的
// 插件是从源码目录加载的，硬 import 会让开发态直接加载失败。所以这里留一张极小的
// 镜像，漂移由 npm/stage.test.mjs 对着 launcher.TARGETS 逐项对账兜住。
const NPM_PLATFORM_PACKAGES: Record<string, string> = {
  "linux-x64": "specrune-linux-x64",
  "linux-arm64": "specrune-linux-arm64",
  "darwin-x64": "specrune-darwin-x64",
  "darwin-arm64": "specrune-darwin-arm64",
  "win32-x64": "specrune-windows-x64",
  "win32-arm64": "specrune-windows-arm64",
};

// 安装器在落盘前把带引号的占位符替换成整机共享 CLI 的绝对路径，但只对 global
// 安装这样做：project 的插件文件通常随仓库提交，绝对路径换台机器就失效。project
// 安装把路径记在机器本地状态里，见 findProjectStateBinary。
const BUNDLED_SPECRUNE = "__SPECRUNE_BUNDLED_BIN__";

// project 安装的状态文件相对项目根。.specrune/.state/ 已在 .specrune/.gitignore
// 内，不会随项目提交，正好放机器本地路径。
const PROJECT_STATE_REL = [".specrune", ".state", "plugins", "opencode.json"];

// hook-serve 写入的自动升级状态；插件只读，路径与 Go 侧 autoUpdateStatePath 一致。
// 提示只允许进易变段（messages），不得进入 system 稳定段
// （req:cli-commands#auto-update-contract / req:injection-chain#injection-pipeline-hard-constraints）。
const AUTO_UPDATE_STATE_REL = [".specrune", ".state", "auto-update.json"];
const AUTO_UPDATE_NOTICE_LIMIT = 16;
// 状态文件在项目目录内，内容不可信：手工命令只接受 Go 侧生成的两条精确形状
// （`specrune update --yes` / `specrune-<adapter> install --scope project --dir <root>`），
// 并限制长度与字符。任意追加文本、超长行都不会进入易变段。
const AUTO_UPDATE_COMMAND = /^(?:specrune update --yes|specrune-[a-z0-9-]+ install --scope project --dir .+)$/;
const AUTO_UPDATE_COMMAND_MAX = 300;
const AUTO_UPDATE_COMMAND_LIMIT = 4;

// .cmd / .bat 在 Windows 上不能直接 spawn，必须经 cmd.exe 拉起。安装器通常注入
// 原生平台二进制，但 SPECRUNE_BIN 也可能被覆盖成 npm 的 shim，所以按扩展名判定，
// 不能假设某个来源一定是原生可执行文件。
function isCmdShim(command: string): boolean {
  return /\.(?:cmd|bat)$/i.test(command);
}

// findPlatformPackageBinary 沿自身目录向上找 node_modules 里的平台包。
// 用纯 fs 查找而不是 createRequire：插件可能被 Bun 以任意路径加载，纯 fs
// 的向上查找对 npm / pnpm / Bun 的 node_modules 布局都成立。
//
// 每层查两处：npm 提升后的 <dir>/node_modules/<pkg>，以及 npm 因版本冲突
// 塞进 <dir>/node_modules/specrune/node_modules/<pkg> 的嵌套副本。
// 迁移期保留，下个大版本删：插件包不再带 specrune 依赖，正常机器上命中前面几档
// （注入的整机共享 CLI / 状态里的 cliPath）就够；留这一档是因为老项目里仍可能
// 躺着按旧契约装的 node_modules/specrune-<os>-<arch>。
function findPlatformPackageBinary(): string | undefined {
  const pkg = NPM_PLATFORM_PACKAGES[`${process.platform}-${process.arch}`];
  if (!pkg) return undefined;
  const binName = process.platform === "win32" ? "specrune.exe" : "specrune";
  for (let dir = path.dirname(fileURLToPath(import.meta.url)); ; dir = path.dirname(dir)) {
    for (const base of [dir, path.join(dir, "node_modules", "specrune")]) {
      const bin = path.join(base, "node_modules", pkg, "bin", binName);
      try {
        if (existsSync(bin) && statSync(bin).isFile()) return bin;
      } catch {
        // 单个坏目录项不该让整条查找失败。
      }
    }
    const parent = path.dirname(dir);
    if (parent === dir) return undefined;
  }
}

// findProjectStateBinary 读 project 安装写入的机器本地状态。插件文件本身是
// 可提交的（保留占位符），cliPath 只存在于 .specrune/.state/ 下；从插件位置
// 向上找最近的 .specrune，命中即读，不再越过项目边界去用父项目的状态。
function findProjectStateBinary(): string | undefined {
  for (let dir = path.dirname(fileURLToPath(import.meta.url)); ; dir = path.dirname(dir)) {
    if (existsSync(path.join(dir, ".specrune"))) {
      let cliPath = "";
      try {
        const parsed = JSON.parse(readFileSync(path.join(dir, ...PROJECT_STATE_REL), "utf8")) as {
          cliPath?: unknown;
        };
        if (typeof parsed.cliPath === "string") cliPath = parsed.cliPath;
      } catch {
        return undefined;
      }
      if (cliPath === "" || !existsSync(cliPath)) return undefined;
      try {
        return statSync(cliPath).isFile() ? cliPath : undefined;
      } catch {
        return undefined;
      }
    }
    const parent = path.dirname(dir);
    if (parent === dir) return undefined;
  }
}

// 定位 specrune 可执行文件。顺序：SPECRUNE_BIN（本地开发期覆盖，与 pi 扩展同名，
// 见 req:cli-contract#env-contract-table）→ global 安装器注入的随包平台二进制 →
// project 安装状态里的 cliPath → npm 平台包向上查找 → PATH。
//
// viaCmd 只由扩展名决定：注入档与 npm 档通常是原生平台二进制，但 SPECRUNE_BIN
// 或安装时的覆盖可能指向 .cmd shim，漏判会让 Windows 上的 spawn 直接 EINVAL。
// win32 的 PATH 回退才需要依次找 specrune.exe、specrune.cmd，都没有时回退
// specrune.exe 让 spawn 报 ENOENT（保留旧失败形态）。
function locateSpecruneBinary(): BinarySpec {
  const fromEnv = (process.env["SPECRUNE_BIN"] || "").trim();
  if (fromEnv) return { command: fromEnv, viaCmd: isCmdShim(fromEnv) };
  // 注入路径可能因用户后来删掉依赖而失效；存在性检查让这种情况自然落到下一档，
  // 而不是每轮 spawn 一个不存在的文件。
  if (BUNDLED_SPECRUNE && !BUNDLED_SPECRUNE.startsWith("__") && existsSync(BUNDLED_SPECRUNE)) {
    return { command: BUNDLED_SPECRUNE, viaCmd: isCmdShim(BUNDLED_SPECRUNE) };
  }
  const fromState = findProjectStateBinary();
  if (fromState) return { command: fromState, viaCmd: isCmdShim(fromState) };
  const viaNpm = findPlatformPackageBinary();
  if (viaNpm) return { command: viaNpm, viaCmd: false };
  if (process.platform !== "win32") return { command: "specrune", viaCmd: false };
  const exe = findOnPath("specrune.exe");
  if (exe) return { command: exe, viaCmd: false };
  const cmd = findOnPath("specrune.cmd");
  if (cmd) return { command: cmd, viaCmd: true };
  return { command: "specrune.exe", viaCmd: false };
}

// spawnSpecrune 按定位结果起进程：.cmd 必须经 cmd.exe /d /s /c 执行，
// windowsVerbatimArguments 保证路径里的空格不被 Node 的二次转义拆坏。
function spawnSpecrune(
  spec: BinarySpec,
  args: string[],
  options: Parameters<typeof spawn>[2],
): ReturnType<typeof spawn> {
  if (!spec.viaCmd) return spawn(spec.command, args, options);
  const line = [`"${spec.command}"`, ...args].join(" ");
  return spawn(process.env["ComSpec"] || "cmd.exe", ["/d", "/s", "/c", `"${line}"`], {
    ...options,
    windowsVerbatimArguments: true,
  });
}

// killSpecrune 终止一次调用的进程树。.cmd 分支的 child.pid 是 cmd.exe，
// 只 kill 它会把真正的 specrune 子进程留下；taskkill /pid <pid> /T /F 才是整棵树。
//
// 只允许在超时 / 管道异常路径调用：成功或 error 应答的收尾必须走
// settleBridgeProcess，否则升级进程会作为 hook-serve 的后代被一起杀掉
// （req:cli-commands#auto-update-contract）。
function killSpecrune(child: ReturnType<typeof spawn>, viaCmd: boolean): void {
  if (!viaCmd) {
    try {
      if (child.exitCode === null) child.kill();
    } catch {
      /* 已经死了 */
    }
    return;
  }
  const pid = child.pid;
  if (pid === undefined) return;
  const fallback = (): void => {
    try {
      if (child.exitCode === null) child.kill();
    } catch {
      /* 已经死了 */
    }
  };
  try {
    const killer = spawn("taskkill", ["/pid", String(pid), "/T", "/F"], {
      windowsHide: true,
      stdio: "ignore",
    });
    killer.on("error", fallback);
  } catch {
    fallback();
  }
}

// BRIDGE_EXIT_GRACE_MS 是成功收尾后等桥自行退出的窗口。
//
// 不能一拿到响应就 taskkill /T /F：升级进程是 hook-serve 的后代，杀树会把它一起
// 杀光，状态停在 started 且同版本不再重试（req:cli-commands#auto-update-contract）。
// 关 stdin 后桥按协议读到 EOF 退出；超过这个窗口仍活着才按异常处理。
const BRIDGE_EXIT_GRACE_MS = 1_000;

// settleBridgeProcess 关 stdin 后给桥一个短窗口自行退出；超时才兜底杀树。
function settleBridgeProcess(child: ReturnType<typeof spawn>, viaCmd: boolean): void {
  if (child.exitCode !== null) return;
  const timer = setTimeout(() => {
    if (child.exitCode === null) killSpecrune(child, viaCmd);
  }, BRIDGE_EXIT_GRACE_MS);
  timer.unref?.();
  child.once("exit", () => clearTimeout(timer));
}

// 拉起失败几乎总是环境性的（二进制不在 PATH、目录不可写、权限不足），重试不会
// 变好，而每次重试都在 Agent 的关键路径上。熔断：连续 3 次失败后冷却 30 秒，期间
// 直接走降级（微缓存 / 跳过注入）。
const MAX_SPAWN_FAILURES = 3;
const RETRY_COOLDOWN_MS = 30_000;

// 逐轮上下文走 stdio 帧管道，不走套接字（req:injection-chain#injection-pipeline-hard-constraints）。
//
// 不做套接字直连：stdio 管道在 Node 与 Bun 上行为一致，而套接字直连只有 Bun 可行，
// 两条注入链会因此分叉（req:architecture#injection-bridge-process-shape）。
//
// 父子同生共死：不设 detached，子进程绑宿主生命周期，宿主退出即随之退出——detached
// 全局进程倍增那类事故在结构上不可能发生。

const HEADER_END = "\r\n\r\n";

function encodeFrame(obj: unknown): Buffer {
  const payload = Buffer.from(JSON.stringify(obj), "utf8");
  return Buffer.concat([Buffer.from(`Content-Length: ${payload.length}${HEADER_END}`, "utf8"), payload]);
}

// decodeFrame 从缓冲里解出**一帧**。
//
// 返回 undefined 表示半截帧（等更多字节），null 表示头坏了（整条流已废）。
// per-call 下只读一帧，所以解出即返回，不做「扫完整个缓冲里所有帧」。
function decodeFrame(buf: Buffer): Record<string, unknown> | undefined | null {
  const headerEnd = buf.indexOf(HEADER_END);
  if (headerEnd < 0) return undefined;
  const m = /Content-Length:\s*(\d+)/i.exec(buf.subarray(0, headerEnd).toString("utf8"));
  if (!m) return null;
  const length = parseInt(m[1], 10);
  const start = headerEnd + HEADER_END.length;
  if (buf.length < start + length) return undefined;
  try {
    return JSON.parse(buf.subarray(start, start + length).toString("utf8")) as Record<string, unknown>;
  } catch {
    return null;
  }
}

// CallFailure 是一次调用没拿到结果的原因。
//
// "error" 与其它几种性质不同：它意味着桥**应答了**（最常见是「没有活跃任务」），
// 属于正常跳过而不是故障——所以消息要单独带出来。
type CallFailure = "dead" | "timeout" | "error";

// CallResult 承载一次调用的结局：结果 / 子进程已死 / 超时 / 对端报错。
// message 只在 reason==="error" 时有值。
type CallResult<T> =
  | { ok: true; value: T }
  | { ok: false; reason: CallFailure; message?: string };

// BRIDGE_FALLBACK_MS 是「等不到响应就降级」的兜底，**不是**决定成败的预算。
//
// 预算档位表只在 Go 侧（`cli/hookserve.go` 按方法查表，req:architecture#bridge-budget-tiers）：两个宿主共用
// 同一座桥，预算只能有一个来源。TS 侧另写常数会让兜底抢在档位之前把请求掐掉，
// 等于把预算又搬回 TS 侧。
//
// 它必须大于桥的最高档（800ms），只负责「桥已经没了 / 卡住了」这两种情况。
const BRIDGE_FALLBACK_MS = 1_500;

// HookBridge 是一次性的注入桥：**每次调用 spawn 一个 `specrune hook-serve` 子进程，
// 发一帧、读一帧、随即终止**（req:architecture#injection-bridge-process-shape）。
//
// 不做常驻：常驻唯一的收益是省掉重复的 `BuildSessionContext`，而缓存 TTL 1s、每轮只调
// 一次，那个节省从不发生（req:architecture#bridge-no-cache）。per-call 后新进程没有状态。
//
// **一次调用只发一帧、只读一帧，所以响应错配在结构上不可能发生**——child 引用、请求表、
// 按 id 配对、存活探测、跨调用的缓冲累积全都不需要，它们都是为常驻服务的。
class HookBridge {
  private failures = 0;
  private cooldownUntil = 0;
  // 微缓存：key = repoRoot|agent → 最近一次成功的稳定段。桥不可用或超时时注入降级用它，
  // Agent 的推理循环不被阻塞（req:architecture#daemon-process-retired /
…[文件过长——中段 8KB 抽样]…
me({ id: 1, method, params }));
      } catch {
        this.noteFailure();
        finish({ ok: false, reason: "dead" } as CallResult<T>);
      }
    });
  }

  // noteFailure 累计失败并决定是否进入冷却。
  //
  // 熔断在 per-call 下**比常驻版更要紧**：常驻版一次会话只 spawn 一次，
  // per-call 每轮都 spawn——二进制缺失会让每轮都失败，熔断是唯一的止血手段。
  //
  // 冷却要**显式告警**而不静默失败：降级还在跑（微缓存 / 跳过），用户看到的
  // 现象只是「规范好像没生效」，没人知道原因（req:architecture#daemon-lifecycle-retired / req:architecture#bridge-degradation-contract）。
  //
  // 告警措辞必须覆盖两类失败：spawn 失败（桥起不来）与超时（桥起来了但不回话）。
  // 只写「无法启动」的话，超时熔断会打出一条与真实故障相反的日志——排障第一步
  // 就是错的，这正是本任务要消灭的那类「说反话的降级」。
  private noteFailure(): void {
    this.failures += 1;
    if (this.failures < MAX_SPAWN_FAILURES) return;
    this.cooldownUntil = Date.now() + RETRY_COOLDOWN_MS;
    this.failures = 0;
    const binary = locateSpecruneBinary();
    process.stderr.write(
      `[specrune] 警告：注入桥已连续 ${MAX_SPAWN_FAILURES} 次没能应答（启动失败或超时未回），接下来 ` +
        `${Math.round(RETRY_COOLDOWN_MS / 1000)} 秒内不再重试，规范注入降级为「跳过/微缓存」。\n` +
        `  排查：① 确认 \`${binary.command}\` 在 PATH 上（可用 SPECRUNE_BIN 指定绝对路径）；\n` +
        `        ② 手动执行 \`${binary.command} hook-serve\` 看前台报错；\n` +
        `        ③ 若能启动但经常超时，多半是仓库过大或 git 探测挂起，先复现本条告警再调预算。\n`,
    );
  }

  // noteSuccess 清零连续失败计数。
  //
  // 为什么必须有：超时是**瞬时**故障（机器某刻繁忙、git 探测偶尔挂起），而
  // 熔断要判的是「连续失败」。若成功不重置，插件进程活得越久、偶发超时攒得越多，
  // 总有一天凑满三次就把一个基本健康的桥打进 30 秒冷却——而告警里写的却是
  // 「连续 3 次」，与事实相反。成功后清零让「连续」名副其实，也让真正卡死的桥
  // （每轮都超时，没有成功可清）照样在三次后冷却。
  private noteSuccess(): void {
    this.failures = 0;
  }

  cacheKey(repoRoot: string, agent?: string): string {
    return `${repoRoot}|${agent ?? ""}`;
  }

  cacheGet(key: string): string | undefined {
    return this.cache.get(key);
  }

  // cacheSet 是有界的（16 条）：宿主进程可能长时间不退出，不封顶就是无界增长。
  cacheSet(key: string, block: string): void {
    if (this.cache.size > 16) {
      const first = this.cache.keys().next().value;
      if (first !== undefined) this.cache.delete(first);
    }
    this.cache.set(key, block);
  }
}

