// 只认显式 `specrune task start/current/finish` 与 `specrune session record`；解析不出
// 任务引用的 start 不写——票据侧 taskRefsMatch 对空引用本来也判不中。
//
// `session record` 在名单里：记录头的 session / platform / task 全靠会话身份，票据是
// OpenCode 下唯一的通道（Pi 走注入变量因而正常）。
//
// 路径前缀不是可选项：Windows 上二进制叫 specrune.exe，且 agent 几乎总是用相对路径调它
// （bin\specrune.exe）。只认裸 `specrune` 会让 Windows 上的票据桥失效，症状是
// 「OpenCode 绑不上 session」，与 worktree 缺陷表象相同。
function parseTicketCommands(command: string): Array<{ name: string; task_ref?: string }> {
  const out: Array<{ name: string; task_ref?: string }> = [];
  const re =
    /\b(?:[^\s;&|]*[\\/])?specrune(?:\.exe)?\s+(?:task\s+(start|current|finish)|session\s+(record))\b(?:\s+([^\s;&|]+))?/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(command)) !== null) {
    const name = m[1] ?? m[2];
    if (!name) continue;
    if (name === "start") {
      const ref = m[3];
      if (!ref || ref.startsWith("-")) continue;
      out.push({ name, task_ref: ref });
    } else {
      out.push({ name });
    }
  }
  return out;
}

// writeShellTicket 在 shell 工具执行前写一张 30 秒票据。
//
// 字段与 TTL 必须与 Go 侧 lookupShellTicketContextKey 的读取逻辑逐项一致
// （.specrune/.runtime/shell-tickets/*.json，TTL 对齐 ShellTicketTTLSeconds）。任何一步
// 失败都静默退化为「无身份」——那是 task start 会显式报错的状态，不是崩溃状态。
function writeShellTicket(ev: ToolEvent, repoRoot: string): void {
  try {
    if (ev.tool !== "shell" || !ev.sessionID) return;
    const input = ev.input as { command?: string; workdir?: string } | undefined;
    if (!input?.command) return;
    const subs = parseTicketCommands(input.command);
    if (subs.length === 0) return; // 没有会话敏感的命令就不需要桥接
    // 只看 `.specrune/` 是否存在：票据服务于显式 CLI 命令（task / session），
    // 项目被禁用时这些命令仍然可用，因此不能因为 `.specrune-disabled` 就
    // 掐断它们的会话身份。也不能因为没有 `.specrune/` 就在每个项目里凭空
    // 制造一个（禁用项目本身已有 `.specrune/`，不受影响）。
    if (!existsSync(path.join(repoRoot, ".specrune"))) return;
    const dir = path.join(repoRoot, ".specrune", ".runtime", "shell-tickets");
    mkdirSync(dir, { recursive: true });
    const now = Date.now() / 1000;
    const ticket = {
      context_key: `opencode_${ev.sessionID}`,
      platform: "opencode",
      cwd: input.workdir || repoRoot,
      created_at_epoch: now,
      expires_at_epoch: now + 30,
      subcommands: subs,
    };
    const file = path.join(dir, `opencode_${ev.sessionID.replace(/[^\w-]/g, "_")}.json`);
    writeFileSync(file, JSON.stringify(ticket), "utf8");
    debug(`写 shell 票据：${subs.map((s) => s.name).join(" / ")}`);
  } catch {
    /* 票据是尽力而为：失败退化为无身份，命令侧会显式报错，不会静默错绑 */
  }
}

// auditToolCall 只读审计：打到 stderr，由 OpenCode 收进日志。不拦截、不改参。
function auditToolCall(ev: ToolEvent): void {
  try {
    let input = "";
    try {
      input = JSON.stringify(ev.input ?? "").slice(0, 200);
    } catch {
      input = String(ev.input).slice(0, 200);
    }
    process.stderr.write(`[specrune-audit] ${ev.tool} ${input}\n`);
  } catch {
    /* 审计是旁路，任何失败都不许影响工具调用 */
  }
}

// 插件入口

// 钩子注册在 setup 闭包里而不是模块顶层：OpenCode 可能以不同项目目录多次实例化同一份
// 插件，repoRoot 必须跟各自的 location.directory 走，共享的只有连接与微缓存。
const setup = async (ctx: {
  location?: { directory?: string };
  session: {
    hook: (name: string, handler: (ev: any) => Promise<void>) => void;
    // get 是宿主 SDK 面：`session.get({ sessionID })` 返回 Session.Info（本插件只消费
    // parentID，req:injection-runtime#workflow-state-decision 子代理判定）。可选：宿主缺它时按主会话处理。
    get?: (args: { sessionID: string }) => Promise<{ parentID?: string } | undefined>;
  };
  tool: { hook: (name: string, handler: (ev: any) => Promise<void>) => void };
}) => {
  const baseDir = ctx.location?.directory || process.cwd();
  // 项目级禁用：没有 .specrune/ 或根目录存在 .specrune-disabled 时完全不注册
  // SpecRune hook。必须在任何 hook 注册之前返回——否则「不激活」只是不注入，
  // 宿主里仍留着 prompt/工具审计钩子。
  if (projectDisabled(resolveRepoRoot(baseDir))) return;
  const repoRoot = () => resolveRepoRoot(baseDir);

  // 只剩 prompt 暂存：注入桥无常驻实例、协议只有一种形状，没有握手要协商的余地。
  ctx.session.hook("prompt", async (ev: PromptEvent) => {
    stashPrompt(ev.sessionID, ev.prompt?.text);
  });

  ctx.session.hook("context", async (ev: ContextEvent) => {
    await injectContext(ev, repoRoot(), ctx.session);
  });

  ctx.tool.hook("execute.before", async (ev: ToolEvent) => {
    const root = repoRoot();
    // 会话中途放上标记时 hook 无法注销，但审计（stderr）必须停下。票据仍要写：
    // task / session 这类显式 CLI 命令不因禁用而失效，OpenCode 的会话身份
    // 只靠这张票据传递。
    if (!projectDisabled(root)) auditToolCall(ev);
    writeShellTicket(ev, root);
  });
};

export default {
  id: "specrune",
  // 字段名必须是 setup：2.0.15 的加载 schema 只认 id + setup/effect 之一，
  // 名字写错（比如 dev 分支的 server）整份插件会被静默拒载。
  setup,
};
